export type AlgorithmId = keyof AlgorithmRegistry;

/** Run one algorithm of this registry through `qgis.host.algorithms.run`. */
export function runAlgorithm<K extends AlgorithmId>(
	qgis: AlgorithmHost,
	id: K,
	params: AlgorithmRegistry[K]["params"],
	options?: HostInvokeOptions,
): Promise<AlgorithmRun<AlgorithmRegistry[K]["result"]>> {
	return runAny<AlgorithmRegistry, K>(qgis, id, params, options);
}
